from itertools import product

# Generate all possible binary sequences of length 10
sequences = list(product([-1, 1], repeat=10))

# Filter sequences based on the given constraints
valid_sequences = []
for seq in sequences:
    if seq[0] == -1 and seq[8] == 1:
        c = [sum(seq[i] * seq[i + k] for i in range(10 - k)) for k in range(1, 10)]
        if c[6] == -1 and sum(x**2 for x in c) <= 20:
            valid_sequences.append(seq)

# Print the first valid sequence or "UNSATISFIABLE" if no sequence exists
if valid_sequences:
    print(valid_sequences[0])
else:
    print("UNSATISFIABLE")
